input.script:
first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
all_open = fold acc = first.items for page in remaining { return acc + page }
cutoff = time.parse("2026-06-03T00:00:00Z")
old = for t in all_open {
    skip if t.created_at == null
    raw = t.created_at
    norm = raw + "T00:00:00Z" if text.length(raw) == 10 else raw
    ts = time.parse(norm)
    skip if ts >= cutoff
    return t
}
escalated = for t in old {
    detail = boundary retry 2 { return get_ticket({ id: t.id }) } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    body = detail.body if detail.body != null else ""
    skip if not ("refund" in text.lower(body))
    upd = boundary retry 2 {
        return update_ticket({ id: t.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return t.id
}
result = submit_result({ answer: { escalated_ticket_ids: escalated } })
return { escalated, recorded: result.recorded }
